#!/usr/bin/env node
/**
 * DSA kursining A7-A12 mavzulari: to'liq nazariya + chizmalar (diagrammalar) + amaliyot (C++/Python/Kotlin kodi).
 * Chizmalar: public/diagrams/*.png (rasm yo'li: /diagrams/<nom>.png).
 *
 * Ishga tushirish: loyiha papkasida (.env.local mavjud joyda):
 *   node seed-dsa-a7-a12.js
 *
 * Xavfsizlik: skriptni qayta-qayta ishga tushirish mumkin (idempotent) —
 *  A7..A12 kodli mavzular topilib, o'chirilib, yangi versiya bilan o'sha order_num da almashtiriladi.
 *  Boshqa mavzularga tegilmaydi.
 */
const fs = require('fs')
const path = require('path')

function loadEnvLocal() {
  const envPath = path.join(__dirname, '.env.local')
  if (!fs.existsSync(envPath)) {
    console.error('XATO: .env.local topilmadi. Bu skriptni loyiha papkasida ishga tushiring.')
    process.exit(1)
  }
  const content = fs.readFileSync(envPath, 'utf-8')
  for (const line of content.split('\n')) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#')) continue
    const idx = trimmed.indexOf('=')
    if (idx === -1) continue
    const key = trimmed.slice(0, idx).trim()
    const value = trimmed.slice(idx + 1).trim()
    if (!process.env[key]) process.env[key] = value
  }
}
loadEnvLocal()

